1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single source of duplicate detection: an owner's identity is its normalized telephone,
9	 * email and household id joined as {@code normalizedTelephone|email|householdId} (email and
10	 * household id empty when absent). Two owners collide only when their whole keys are equal, so
11	 * members of one household with different telephones stay distinct.
12	 */
13	public final class IdentityKey {
14	
15	    private IdentityKey() {
16	    }
17	
18	    /** The derived identity key of {@code owner}; telephone is already E.164-normalized upstream. */
19	    public static String of(Owner owner) {
20	        return blank(owner.getTelephone()) + "|" + blank(owner.getEmail()) + "|" + blank(owner.getHouseholdId());
21	    }
22	
23	    /** {@code true} when an existing owner has the exact same identity key as {@code candidate}. */
24	    static boolean isDuplicate(Owner candidate, Collection<Owner> existing) {
25	        String key = of(candidate);
26	        return existing.stream().anyMatch(other -> of(other).equals(key));
27	    }
28	
29	    private static String blank(String value) {
30	        return value == null ? "" : value;
31	    }
32	}
