1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The single Luhn check digit (0-9) computed over the digits of an owner's customerCode,
7	 * so a code can be validated without recomputing how it was built.
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    /** The Luhn check digit over the digits contained in {@code owner}'s customerCode. */
15	    public static int of(Owner owner) {
16	        return luhn(owner.getCustomerCode());
17	    }
18	
19	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
20	    static int luhn(String value) {
21	        int sum = 0;
22	        boolean dbl = true;
23	        for (int i = value.length() - 1; i >= 0; i--) {
24	            int d = value.charAt(i) - '0';
25	            if (d < 0 || d > 9) {
26	                continue;
27	            }
28	            if (dbl && (d *= 2) > 9) {
29	                d -= 9;
30	            }
31	            sum += d;
32	            dbl = !dbl;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
