1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Builds an owner's customerCode in the form {@code <CITY3>-<LAST3>-<NNNN>}: the
9	 * upper-cased first three letters of the city, the first three of the lastName, and
10	 * a per-city 4-digit sequence (one more than the owners already in that city).
11	 */
12	final class CustomerCodes {
13	
14	    private CustomerCodes() {
15	    }
16	
17	    /** The {@code <CITY3>-<LAST3>-<NNNN>} code for {@code owner} given the {@code existing} owners. */
18	    static String build(Owner owner, Collection<Owner> existing) {
19	        long inCity = existing.stream()
20	            .filter(other -> owner.getCity().equalsIgnoreCase(other.getCity()))
21	            .count();
22	        return prefix(owner.getCity()) + "-" + prefix(owner.getLastName())
23	            + String.format("-%04d", inCity + 1);
24	    }
25	
26	    private static String prefix(String value) {
27	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
28	    }
29	}
