27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    public String getPostcode() {
59	        return this.postcode;
60	    }
61	
62	    public void setPostcode(String postcode) {
63	        this.postcode = postcode;
64	    }
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "customer_code")
70	    private String customerCode;
71	
72	    @Column(name = "household_id")
73	    private String householdId;
74	
75	    @org.hibernate.annotations.Formula(
76	        "(select cast(count(*) as integer) from owners hm where hm.household_id = household_id)")
77	    private Integer householdSize;
78	
79	    public Integer getHouseholdSize() {
80	        return this.householdSize;
81	    }
82	
83	    public void setHouseholdSize(Integer householdSize) {
84	        this.householdSize = householdSize;
85	    }
86	
87	    @Column(name = "namesake_count")
88	    private Integer namesakeCount;
89	
90	    public Integer getNamesakeCount() { return this.namesakeCount; }
91	
92	    public void setNamesakeCount(Integer namesakeCount) { this.namesakeCount = namesakeCount; }
93	
94	    public String getCustomerCode() {
95	        return this.customerCode;
96	    }
97	
98	    public void setCustomerCode(String customerCode) {
99	        this.customerCode = customerCode;
100	    }
101	
102	    public String getHouseholdId() {
103	        return this.householdId;
104	    }
105	
106	    public void setHouseholdId(String householdId) {
107	        this.householdId = householdId;
108	    }
109	
110	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
111	    private Set<Pet> pets;
112	
113	    public LocalDate getRegistrationDate() {
114	        return this.registrationDate;
115	    }
116	
117	    public void setRegistrationDate(LocalDate registrationDate) {
118	        this.registrationDate = registrationDate;
119	    }
120	
121	    @PrePersist
122	    void defaultRegistrationDate() {
123	        if (this.registrationDate == null) {
124	            this.registrationDate = LocalDate.now();
125	        }
126	        this.registrationDate = BusinessDays.roll(this.registrationDate);
127	    }
128	
129	    public String getEmail() {
130	        return this.email;
131	    }
132	
133	    public void setEmail(String email) {
134	        this.email = email;
135	    }
136	
137	    public String getAddress() {
138	        return this.address;
139	    }
140	
141	    public void setAddress(String address) {
142	        this.address = address;
143	    }
144	
145	    public String getCity() {
146	        return this.city;
147	    }
148	
149	    public void setCity(String city) {
150	        this.city = city;
151	    }
152	
153	    public String getTelephone() {
154	        return this.telephone;
155	    }
156	
157	    public void setTelephone(String telephone) {
158	        this.telephone = telephone;
159	    }
160	
161	    protected Set<Pet> getPetsInternal() {
162	        if (this.pets == null) {
163	            this.pets = new HashSet<>();
164	        }
165	        return this.pets;
166	    }
167	
168	    protected void setPetsInternal(Set<Pet> pets) {
169	        this.pets = pets;
170	    }
171	
172	    public List<Pet> getPets() {
173	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
174	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
175	        return Collections.unmodifiableList(sortedPets);
176	    }
177	
178	    public void setPets(List<Pet> pets) {
179	        this.pets = new HashSet<>(pets);
180	    }
181	
182	    public void addPet(Pet pet) {
183	        getPetsInternal().add(pet);
184	        pet.setOwner(this);
185	    }
186	
187	    /**
188	     * Return the Pet with the given name, or null if none found for this Owner.
189	     *
190	     * @param name to test
191	     * @return true if pet name is already in use
192	     */
193	    public Pet getPet(String name) {
194	        return getPet(name, false);
195	    }
196	
197	    /**
198	     * Return the Pet with the given name, or null if none found for this Owner.
199	     *
200	     * @param name to test
201	     * @return true if pet name is already in use
202	     */
203	    public Pet getPet(String name, boolean ignoreNew) {
204	        name = name.toLowerCase();
205	        for (Pet pet : getPetsInternal()) {
206	            if (!ignoreNew || !pet.isNew()) {
207	                String compName = pet.getName();
208	                compName = compName.toLowerCase();
209	                if (compName.equals(name)) {
210	                    return pet;
211	                }
212	            }
213	        }
214	        return null;
215	    }
216	
217	    public Pet getPet(Integer petId) {
218	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
219	    }
220	
221	    @Override
222	    public String toString() {
223	        return new ToStringCreator(this)
224	
225	            .append("id", this.getId())
226	            .append("new", this.isNew())
227	            .append("lastName", this.getLastName())
228	            .append("firstName", this.getFirstName())
229	            .append("address", this.address)
230	            .append("city", this.city)
231	            .append("telephone", this.telephone)
232	            .toString();
233	    }
234	}
